<?php
namespace Modules\Ran\Http\Requests;use Illuminate\Foundation\Http\FormRequest;
class SaleRequest extends FormRequest{public function authorize():bool{return auth()->check();}public function rules():array{return ['invoice_date'=>'required|date','customer_contact_id'=>'nullable|integer','customer_name'=>'nullable|string|max:255','customer_mobile'=>'nullable|string|max:40','customer_email'=>'nullable|email|max:255','discount_amount'=>'nullable|numeric|min:0','tax_amount'=>'nullable|numeric|min:0','rounding_amount'=>'nullable|numeric','notes'=>'nullable|string|max:2000','terms'=>'nullable|string|max:4000','lines'=>'required|array|min:1','lines.*.stock_lot_id'=>'required|integer','lines.*.quantity'=>'required|numeric|min:0.0001','lines.*.gross_weight'=>'nullable|numeric|min:0','lines.*.net_weight'=>'nullable|numeric|min:0','lines.*.stone_weight'=>'nullable|numeric|min:0','lines.*.metal_rate'=>'nullable|numeric|min:0','lines.*.metal_value'=>'nullable|numeric|min:0','lines.*.stone_value'=>'nullable|numeric|min:0','lines.*.making_charge'=>'nullable|numeric|min:0','lines.*.other_charge'=>'nullable|numeric|min:0','lines.*.discount_amount'=>'nullable|numeric|min:0','lines.*.tax_amount'=>'nullable|numeric|min:0','lines.*.unit_price'=>'required|numeric|min:0'];}public function withValidator($v):void{$v->after(function($v){if(!$this->customer_contact_id&&!$this->customer_name)$v->errors()->add('customer_name','Select a customer or enter a walk-in customer name.');});}}
